package com.changyu.ochat;

import android.app.Activity;
import android.content.*;
import android.text.Spanned;
import android.view.*;
import android.widget.*;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import java.lang.reflect.*;
import java.util.*;
import static org.junit.Assert.*;

@RunWith(AndroidJUnit4.class)
public class FeatureUpdateRegressionTest {
 @Test public void migrationCheckedOnlyAndFallback()throws Exception{JSONObject p=new JSONObject().put("id","p").put("apiKey","secret").put("modelId","old").put("model","Old name").put("outputTokens","1234").put("temperature","0.3").put("custom","keep");ModelStore.migrateProvider(p);ModelStore.migrateProvider(p);assertEquals(1,p.getJSONArray("models").length());assertEquals("1234",ModelStore.selected(p).getString("outputTokens"));ModelStore.addChecked(p,new String[]{"unchecked","new","new"},new boolean[]{false,true,true});assertEquals(2,p.getJSONArray("models").length());assertEquals("secret",p.getString("apiKey"));assertEquals("keep",p.getString("custom"));p.getJSONArray("models").remove(0);ModelStore.fallback(p);assertEquals("new",p.getString("selectedModelId"));}
 @Test public void numericRanges(){assertEquals(0,ModelStore.range("0",2),0);assertEquals(2,ModelStore.range("2",2),0);assertEquals(1,ModelStore.range("1",1),0);for(String s:new String[]{"NaN","Infinity","-0.1","2.1",""})try{ModelStore.range(s,2);fail(s);}catch(IllegalArgumentException expected){}}
 @Test public void markdownHasStructuredSpans(){Context context=InstrumentationRegistry.getInstrumentation().getTargetContext();Spanned text=MarkdownRenderer.create(context).toMarkdown("# Heading\n\n**bold** and ~~strike~~ and [link](https://example.com)\n\n- one\n- two\n\n```java\nint x = 1;\n```\n\n| A | B |\n| --- | --- |\n| x | y |");assertTrue(text.toString().contains("Heading"));assertFalse(text.toString().contains("**bold**"));Set<String> names=new HashSet<>();for(Object span:text.getSpans(0,text.length(),Object.class))names.add(span.getClass().getSimpleName());assertTrue(names.toString(),names.contains("HeadingSpan"));assertTrue(names.toString(),names.contains("TableSpan"));assertTrue(names.toString(),names.contains("CodeBlockSpan"));assertTrue(names.toString(),names.contains("StrikethroughSpan"));assertTrue(names.toString(),names.contains("LinkSpan"));}
 @Test public void promptAndDescriptorRestoration()throws Exception{android.app.Instrumentation ins=InstrumentationRegistry.getInstrumentation();Context context=ins.getTargetContext();SharedPreferences prefs=context.getSharedPreferences("chat",Context.MODE_PRIVATE);Map<String,?> backup=new HashMap<>(prefs.getAll());Activity screen=null;try{JSONObject descriptor=new JSONObject().put("uri","content://missing/document/1").put("mime","application/pdf").put("type","document").put("displayName","test.pdf");JSONObject session=new JSONObject().put("id","feature-test").put("title","test").put("messages",new JSONArray().put(new JSONObject().put("user",true).put("text","hello").put("attachments",new JSONArray().put(descriptor))));prefs.edit().clear().putString("sessions",new JSONArray().put(session).toString()).putString("currentSessionId","feature-test").commit();screen=ins.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Activity activity=screen;Throwable[] error={null};ins.runOnMainSync(()->{try{Method build=MainActivity.class.getDeclaredMethod("buildMessages");build.setAccessible(true);JSONArray noPrompt=(JSONArray)build.invoke(activity);assertEquals(1,noPrompt.length());prefs.edit().putString("systemPrompt","system-only").apply();JSONArray withPrompt=(JSONArray)build.invoke(activity);assertEquals(2,withPrompt.length());assertEquals("system",withPrompt.getJSONObject(0).getString("role"));assertEquals("system-only",withPrompt.getJSONObject(0).getString("content"));Field field=MainActivity.class.getDeclaredField("messageList");field.setAccessible(true);assertTrue(text((View)field.get(activity)).contains("test.pdf"));JSONObject stored=new JSONArray(prefs.getString("sessions","[]")).getJSONObject(0).getJSONArray("messages").getJSONObject(0);assertEquals(descriptor.toString(),stored.getJSONArray("attachments").getJSONObject(0).toString());assertEquals("hello",stored.getString("text"));}catch(Throwable e){error[0]=e;}});if(error[0]!=null)throw new AssertionError(error[0]);}finally{if(screen!=null){Activity activity=screen;ins.runOnMainSync(activity::finish);ins.waitForIdleSync();}SharedPreferences.Editor edit=prefs.edit().clear();for(Map.Entry<String,?> e:backup.entrySet()){Object v=e.getValue();if(v instanceof String)edit.putString(e.getKey(),(String)v);else if(v instanceof Boolean)edit.putBoolean(e.getKey(),(Boolean)v);else if(v instanceof Integer)edit.putInt(e.getKey(),(Integer)v);else if(v instanceof Long)edit.putLong(e.getKey(),(Long)v);else if(v instanceof Float)edit.putFloat(e.getKey(),(Float)v);}edit.commit();}}
 private static String text(View v){StringBuilder s=new StringBuilder();if(v instanceof TextView)s.append(((TextView)v).getText());if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)s.append(text(g.getChildAt(i)));}return s.toString();}
}
